#pragma once
#include "rinkfit/joint_packed_cost_adapter_v1.hpp"
#include "rinkfit/joint_finite_station_branch.hpp"
#include <functional>
namespace rinkfit {
// Strict solver admission is separate from same-objective coordinate/Jacobian
// equivalence QA. A failed current coarse root is an honest invalid initial
// chart; packing never turns it into an IFT or source-quality pass.
class JointPackedStrictTrialAdmissionV1 {
 struct Chart {std::size_t raw=0;int path=0,material=0,kind=0,geometry_piece=-1,query_piece=-1;double lower=0,upper=1;std::shared_ptr<const JointQuery>query;bool all_constant=false,checked=false;};
 struct Pin {const double*data=nullptr;std::vector<double>values;};
 JointProblemBuilder*core_;ceres::Problem*original_;std::vector<Chart>charts_;std::vector<Pin>pins_;bool ready_=true;std::string initial_failure_;
 static int geometry_piece(const JointEventModel&m,const JointObservation&o,double s){const auto&p=m.materials.at(o.material).paths.at(o.path);if(p.kind!=6)return -1;auto l=o.layout(m);const int count=l.geometry_indices.empty()?int(m.blocks.at(p.geometry_block).values.size())-l.geometry_offset:int(l.geometry_indices.size()),n=count/2;if(n<2)return -1;const int segments=p.closed?n:n-1;return std::min(segments-1,int(std::floor(s*segments)));}
 static int query_piece(const JointQuery*q,double a){if(!q||!q->den.empty())return -1;auto it=std::upper_bound(q->alpha.begin(),q->alpha.end(),a);return it==q->alpha.end()?int(q->alpha.size())-2:int(it-q->alpha.begin())-1;}
 public:
 JointPackedStrictTrialAdmissionV1(JointProblemBuilder&core,ceres::Problem&original):core_(&core),original_(&original){std::set<const double*>pinned;for(std::size_t i=0;i<core.packet.rows.size();++i){const auto&o=core.packet.rows[i];if(!o.active)continue;Chart c;c.raw=i;c.path=o.path;c.material=o.material;c.kind=o.kind;c.query=o.query;const double s=o.kind==1?o.station:core.station[i];if(o.kind==1){if(o.query||!core.model.materials.at(o.material).paths.at(o.path).physical_point){ready_=false;initial_failure_="fixed entity gained station/Query semantics";break;}}else{std::size_t containing=0;for(auto v:joint_source_station_components(o,core.model,o.path))if(s>=v[0]&&s<=v[1]){c.lower=v[0];c.upper=v[1];++containing;}if(containing!=1){ready_=false;initial_failure_="current station has no unique legal connected source component at raw "+std::to_string(i);break;}}c.geometry_piece=geometry_piece(core.model,o,s);c.query_piece=query_piece(o.query.get(),core.alpha[i]);c.all_constant=true;auto add=[&](const double*p){if(!original.HasParameterBlock(p)||!original.IsParameterBlockConstant(p)){c.all_constant=false;return;}if(pinned.insert(p).second)pins_.push_back({p,std::vector<double>(p,p+original.ParameterBlockSize(p))});};const auto layout=o.layout(core.model);for(auto bi:layout.block_ids)add(core.model.blocks[bi].values.data());if(o.kind!=1)add(&core.station[i]);add(&core.row[i]);if(o.query)add(&core.alpha[i]);charts_.push_back(std::move(c));}}
 bool operator()(const JointNuisanceComponentPackV1&pack,std::string*why){auto fail=[&](const std::string&s){if(why)*why=s;return false;};if(!ready_)return fail(initial_failure_);for(const auto&p:pins_)if(std::memcmp(p.data,p.values.data(),p.values.size()*sizeof(double)))return fail("constant protected dependency changed after strict chart construction");
  for(auto&c:charts_){const auto&source=core_->packet.rows.at(c.raw);if(source.path!=c.path||source.material!=c.material||source.kind!=c.kind||source.query.get()!=c.query.get())return fail("strict finite source/typed Query chart generation changed");if(c.all_constant&&c.checked)continue;const double s=source.kind==1?source.station:*pack.view(&core_->station[c.raw]),r=*pack.view(&core_->row[c.raw]),a=source.query?*pack.view(&core_->alpha[c.raw]):core_->alpha[c.raw];if(!std::isfinite(s)||s<c.lower||s>c.upper||!std::isfinite(r)||r<0||r>1079||!source.station_allowed(core_->model,c.path,s))return fail("trial outside original finite source/row branch at raw "+std::to_string(c.raw));if(source.query&&(!std::isfinite(a)||a<source.query->alpha.front()||a>source.query->alpha.back()))return fail("trial outside typed finite Query alpha branch");if(geometry_piece(core_->model,source,s)!=c.geometry_piece||query_piece(source.query.get(),a)!=c.query_piece)return fail("trial crossed a finite geometry/Query differential piece; explicit equivalent chart restart required");
   JointObservation o=source;o.station=s;o.row=r;o.alpha=a;if(o.kind!=1){o.source_station_intervals={{c.lower,c.upper}};o.station_domain_path=c.path;}JointRowEvaluation q;q.model=&core_->model;q.layout=o.layout(core_->model);q.observation=&o;auto pointers=core_->model.pointers(q.layout);for(std::size_t k=0;k<q.layout.block_ids.size();++k)q.parameter_sizes[int(k)]=int(core_->model.blocks.at(q.layout.block_ids[k]).values.size());std::array<double,3>x;Eigen::Matrix3d J;if(!q.local_solution_uncached(pointers.data(),s,&x,&J))return fail("no nonsingular same-branch native RS/Query root at raw "+std::to_string(c.raw));if(x[0]<c.lower||x[0]>c.upper||geometry_piece(core_->model,source,x[0])!=c.geometry_piece||query_piece(source.query.get(),x[2])!=c.query_piece)return fail("local root changed finite connected/differential branch");
   for(const auto&z:std::array<std::array<double,2>,2>{{{{s,r}},{{x[0],x[1]}}}}){auto projection=core_->model.predict_explicit(q.layout,z[0],z[1],pointers.data());if(!projection.valid()||!core_->model.visibility(q.layout,z[0],z[1],pointers.data()).visible())return fail("trial/root physical visibility or ray domain invalid at raw "+std::to_string(c.raw));for(int kind:{5,6})if(core_->model.measurement_domain(q.layout,z[0],pointers.data(),kind)>0)return fail("trial/root finite paint measurement domain invalid");}if(c.all_constant)c.checked=true;
  }return true;
 }
 eventio::Json report()const{return {{"schema","rinkfit.packed_strict_same_finite_root_trial_policy.v1"},{"initial_chart_metadata_ready",ready_},{"initial_metadata_failure",initial_failure_},{"active_charts",charts_.size()},{"constant_dependency_pins",pins_.size()},{"current_local_roots_not_claimed_without_actual_trial_check",true},{"no_root_rejects_whole_trial",true},{"fixed_entities_only_RS",true},{"source_rows_dropped_or_zeroed",false},{"whole_readout_unique_certificate_replaced",false}};}
};
class JointPackedEvaluationV1 final:public ceres::EvaluationCallback {
 JointNuisanceComponentPackV1*pack_;ceres::EvaluationCallback*downstream_;std::function<bool(const JointNuisanceComponentPackV1&,std::string*)>admit_;std::shared_ptr<JointPackedTrialStatusV1>status_;std::string policy_id_;
 public:
 JointPackedEvaluationV1(JointNuisanceComponentPackV1&pack,ceres::EvaluationCallback*downstream,std::function<bool(const JointNuisanceComponentPackV1&,std::string*)>admit,std::string policy_id):pack_(&pack),downstream_(downstream),admit_(std::move(admit)),status_(std::make_shared<JointPackedTrialStatusV1>()),policy_id_(std::move(policy_id)){if(!admit_||policy_id_.empty())throw std::runtime_error("packed evaluation requires explicit trial admission policy identity");}
 const auto&status()const{return status_;}
 void PrepareForEvaluation(bool jacobians,bool new_point)override{status_->valid.store(false,std::memory_order_release);status_->reason.clear();try{if(!pack_->validate_values(&status_->reason)||!admit_(*pack_,&status_->reason)){++status_->rejected;return;}if(!pack_->sync_original_from_packed(&status_->reason)){++status_->rejected;return;}if(downstream_)downstream_->PrepareForEvaluation(jacobians,new_point);++status_->prepared;status_->valid.store(true,std::memory_order_release);}catch(const std::exception&e){status_->reason=e.what();++status_->rejected;}}
 // Existing complete-state restoration remains authoritative. Call this after
 // its rollback/resume, before the next evaluation or accepted-state export.
 void reset_from_original(){pack_->pull_from_original();status_->valid.store(false,std::memory_order_release);status_->reason="complete original state restored; prepare required";}
 void capture_accepted(){if(!status_->valid.load())throw std::runtime_error("cannot accept an unprepared/invalid packed trial");pack_->capture_accepted();}
 void restore_accepted_auxiliaries(){pack_->restore_accepted();status_->valid.store(false,std::memory_order_release);status_->reason="accepted auxiliary rollback; prepare required";}
 eventio::Json report()const{return {{"schema","rinkfit.atomic_packed_to_original_evaluation_callback.v1"},{"policy_id",policy_id_},{"prepared",status_->prepared},{"rejected",status_->rejected},{"valid",status_->valid.load()},{"reason",status_->reason},{"GPU_forward_callback_reused",downstream_!=nullptr},{"all_validation_before_any_auxiliary_commit",true},{"complete_CP_or_four_array_layout_changed",false}};}
};
} // namespace rinkfit
